      hal_log_err("Failed to set PWM%d channel B: %d\n", priv->pwm_id, ret);
      return ret;
    }
  }

  ret = hal_pwm_enable(priv->pwm_id);
  if (ret < 0) {
    hal_log_err("Failed to enable PWM%d: %d\n", priv->pwm_id, ret);
    return ret;
  }

  priv->frequency = info->frequency;
  priv->enabled = true;

  return OK;
}
