  memcpy(&arg->action1, a1, sizeof(struct aic_pwm_action));

  pwm_reg_enable(PWM_CKCTL, PWM_CKCTL_PWM_ON(ch), 1);
  pwm_writel(PWM_SHADOW_SEL_ZRQ_PRD, PWM_CMPCTL(ch));
