  arg = &g_pwm_args[ch];

  if (!arg->available) {
    hal_log_err("ch%d is unavailable\n", ch);
    return -EINVAL;
  }

  if (cnt > PWM_TBPRD_MAX) {
    hal_log_err("ch%d period %d is too big\n", ch, cnt);
    return -ERANGE;
  }

  arg->period = cnt;

  pwm_writel(arg->period, PWM_TBPRD(ch));

