static int pwm_setup(struct pwm_lowerhalf_s *dev)
{
  struct aic_pwm_lowerhalf_s *priv = to_aic_pwm(dev);
  struct aic_pwm_action action0 = {
    .CBD = PWM_ACT_NONE,
    .CBU = PWM_ACT_NONE,
    .CAD = PWM_ACT_NONE,
    .CAU = PWM_ACT_LOW,
    .PRD = PWM_ACT_NONE,
    .ZRO = PWM_ACT_HIGH
  };
  struct aic_pwm_action action1 = {
